export async function createEmbeddingRequest(input:{chunkId:string;idempotencyKey:string}):Promise<EmbeddingRequest>{return tx(async client=>{const existing=(await client.query("SELECT request.* FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,chunk_id uuid,profile_version_id uuid,expected_source_hash text,expected_chunk_hash text,status text,attempt_count integer,idempotency_key text,next_retry_at timestamptz,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,updated_at timestamptz,embedding_freeze jsonb,embedding_execution_key uuid,embedding_lease_expires_at timestamptz,embedding_model_state text) WHERE record.status='active') request JOIN (SELECT * FROM new_design.embedding_chunks WHERE record_kind='chunk') chunk ON chunk.id=request.chunk_id WHERE chunk.id=$1 AND request.idempotency_key=$2",[input.chunkId,input.idempotencyKey])).rows[0];if(existing)return mapRequest(existing);const chunk=assertFound((await client.query("SELECT chunk.*,source.source_hash FROM (SELECT * FROM new_design.embedding_chunks WHERE record_kind='chunk') chunk JOIN (SELECT fields.*,source_text.chunk_text content_text FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_source_snapshot' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,space_id uuid,book_id uuid,profile_version_id uuid,dependency_source_resource_id uuid,source_kind text,source_stable_id uuid,source_version_id uuid,source_revision integer,source_hash text,title text,chunk_recipe_hash text,status text,created_by text,created_at timestamptz,stale_at timestamptz) JOIN new_design.embedding_chunks source_text ON source_text.id=fields.id AND source_text.source_snapshot_id=fields.id AND source_text.book_id=fields.book_id AND source_text.profile_version_id=fields.profile_version_id AND source_text.record_kind='source' WHERE record.status='active') source ON source.id=chunk.source_snapshot_id WHERE chunk.id=$1",[input.chunkId])).rows[0],"语义分块不存在。");if(chunk.status!=="current")throw new NewDesignError("过期分块不能请求嵌入。",409);const row=(await (async()=>{const values={status:"pending",attempt_count:0,next_retry_at:null,last_error_code:"",last_error_detail:"",retryable:false,created_at:new Date().toISOString(),updated_at:new Date().toISOString(),embedding_freeze:null,embedding_execution_key:null,embedding_lease_expires_at:null,embedding_model_state:"not_sent",id:randomUUID(),book_id:chunk.book_id,chunk_id:chunk.id,profile_version_id:chunk.profile_version_id,expected_source_hash:chunk.source_hash,expected_chunk_hash:chunk.content_hash,idempotency_key:input.idempotencyKey};await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`embedding_request:${values.book_id}:${values.idempotency_key}`]);if((await listRecordCards(client,"embedding_request",{includeArchived:true,where:{book_id:values.book_id,idempotency_key:values.idempotency_key}})).length)throw new NewDesignError("原请求键已存在，请核对原回执。",409);const row=await createRecordCard(client,{id:String(values.id),spaceId:String(assertFound((await client.query("SELECT space_id FROM new_design.books WHERE id=$1",[values.book_id])).rows[0],"书籍不存在。").space_id),typeKey:"embedding_request",title:"embedding_request",values});return{rows:[row],rowCount:1};})()).rows[0];return mapRequest(row);});}
export async function readEmbeddingRequestWith(client:PoolClient,id:string):Promise<EmbeddingRequestDetail>{const request=mapRequest(assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,chunk_id uuid,profile_version_id uuid,expected_source_hash text,expected_chunk_hash text,status text,attempt_count integer,idempotency_key text,next_retry_at timestamptz,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,updated_at timestamptz,embedding_freeze jsonb,embedding_execution_key uuid,embedding_lease_expires_at timestamptz,embedding_model_state text) WHERE record.status='active') embedding_request_record WHERE id=$1",[id])).rows[0],"嵌入请求不存在。")),attempts=(await client.query("SELECT * FROM (SELECT fields.*,CASE WHEN record_version.values->'embedding_reply' IS NOT NULL AND record_version.values->'embedding_reply'<>'null'::jsonb THEN (SELECT ((record_version.values->'embedding_reply')-'vectorId')||jsonb_build_object('vector',reply_vector.response_vector) FROM new_design.embedding_vectors reply_vector WHERE reply_vector.id=fields.id AND reply_vector.record_kind='attempt' AND reply_vector.attempt_id=fields.id AND reply_vector.request_id=fields.request_id) ELSE NULL END embedding_reply FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_attempt' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,request_id uuid,attempt_number integer,status text,provider_request_ref text,error_code text,error_detail text,retryable boolean,started_at timestamptz,ended_at timestamptz,embedding_reply_hash text,embedding_execution jsonb) WHERE record.status='active') embedding_attempt_record WHERE request_id=$1 ORDER BY attempt_number",[id])).rows.map(mapAttempt),results=(await client.query("SELECT id,request_id,attempt_id,chunk_id,profile_version_id,observed_source_hash,observed_chunk_hash,outcome,vector_hash,detail,created_at FROM (SELECT fields.*, (SELECT result_vector.embedding FROM new_design.embedding_vectors result_vector WHERE result_vector.id=fields.id AND result_vector.record_kind='result' AND result_vector.result_id=fields.id AND result_vector.chunk_id=fields.chunk_id AND result_vector.profile_version_id=fields.profile_version_id) vector_value FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_result' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,request_id uuid,attempt_id uuid,chunk_id uuid,profile_version_id uuid,observed_source_hash text,observed_chunk_hash text,outcome text,vector_hash text,detail text,created_at timestamptz) WHERE record.status='active') embedding_result_record WHERE request_id=$1 ORDER BY created_at",[id])).rows.map(mapResult);return{...request,attempts,results};}
export async function getEmbeddingRequest(id:string):Promise<EmbeddingRequestDetail>{const client=await(await getNewDesignPool()).connect();try{return await readEmbeddingRequestWith(client,id);}finally{client.release();}}
export async function listEmbeddingRequests(input:{bookId:string;status?:EmbeddingRequest["status"];limit:number}):Promise<EmbeddingRequest[]>{const pool=await getNewDesignPool();return(await pool.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,chunk_id uuid,profile_version_id uuid,expected_source_hash text,expected_chunk_hash text,status text,attempt_count integer,idempotency_key text,next_retry_at timestamptz,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,updated_at timestamptz,embedding_freeze jsonb,embedding_execution_key uuid,embedding_lease_expires_at timestamptz,embedding_model_state text) WHERE record.status='active') embedding_request_record WHERE book_id=$1 AND ($2::text IS NULL OR status=$2) ORDER BY created_at DESC,id DESC LIMIT $3",[input.bookId,input.status??null,input.limit])).rows.map(mapRequest);}
export async function startEmbeddingAttempt(requestId:string):Promise<EmbeddingAttempt>{return tx(async client=>{const request=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='embedding_request' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,chunk_id uuid,profile_version_id uuid,expected_source_hash text,expected_chunk_hash text,status text,attempt_count integer,idempotency_key text,next_retry_at timestamptz,last_error_code text,last_error_detail text,retryable boolean,created_at timestamptz,updated_at timestamptz,embedding_freeze jsonb,embedding_execution_key uuid,embedding_lease_expires_at timestamptz,embedding_model_state text) WHERE record.status='active') embedding_request_record WHERE id=$1 FOR UPDATE",[requestId])).rows[0],"嵌入请求不存在。");if(!["pending","retry_scheduled","failed"].includes(String(request.status)))throw new NewDesignError("嵌入请求当前不能开始尝试。",409);const attempt=Number(request.attempt_count)+1,row=(await (async()=>{const values={provider_request_ref:null,error_code:"",error_detail:"",retryable:false,started_at:new Date().toISOString(),ended_at:null,embedding_reply:null,embedding_reply_hash:null,embedding_execution:null,id:randomUUID(),request_id:requestId,attempt_number:attempt,status:"running"};const row=await createRecordCard(client,{id:String(values.id),spaceId:DEFAULT_SPACE_ID,typeKey:"embedding_attempt",title:"embedding_attempt",values});return{rows:[row],rowCount:1};})()).rows[0];await (async()=>{const current=await requireRecordCard(client,String(requestId),"embedding_request","原记录不存在。",{includeArchived:true,lock:true});const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"embedding_request",values:{...current,status:"running",attempt_count:attempt,updated_at:new Date().toISOString(),revision:Number(current.revision)+1}});return{rows:[row],rowCount:1};})();return mapAttempt(row);});}
