export async function buildEmbeddingGeneration(input:{bookId:string;profileVersionId:string;idempotencyKey:string;createdBy:string}):Promise<EmbeddingIndexGeneration>{return tx(client=>buildEmbeddingGenerationWith(client,input));}
export async function activateEmbeddingGeneration(id:string):Promise<EmbeddingIndexGeneration>{return tx(async client=>{await client.query("SELECT new_design.activate_embedding_generation($1)",[id]);return mapGeneration(assertFound((await client.query("SELECT * FROM new_design.embedding_generations WHERE id=$1",[id])).rows[0],"语义索引分代不存在。"));});}

